select * from customer

-- Q1 What is the total revenue generated by male vs. female customer?

select gender, SUM(purchase_amount) as revenue
from customer
group by gender

-- Q2 which customers used discount but still spend more than the average purchase amount?

select customer_id, purchase_amount from customer
where discount_amount = yes and purchase_amount >= (select AVG(purchase_amount) 
from customer)

-- Q3 which are the top 5 products with highest average review rating?

select item_purchased, ROUND(AVG(review_rating::numeric), 2 ) as "Average Product Rating"
from customer
group by item_purchased
order by avg(review_rating) desc
limit 5;

-- Q4 compare the average purchase Amounts between standard and express Shipping.

select shipping_type, ROUND(avg(purchase_amount),2) from customer
where shipping_type in ('Standard', 'Express')
group by shipping_type

-- Q5 Do suscribed customers spend more? compare average spend and total revenue 
-- between suscriber and non-subscriber.

select subscription_status,
COUNT(customer_id) as total_customers,
ROUND(avg(purchase_amount),2) as avg_spend,
ROUND(sum(purchase_amount),2) as total_revenue
from customer
group by subscription_status
order by total_revenue, avg_spend desc;

-- Q6 which 5 product have the highest percentage of purchases with discounts applied?

select item_purchased,
ROUND(100*SUM(CASE WHEN discount_applied = 'Yes' then 1 else 0 end)/count(*),2) as discount_rate 
from customer
group by item_purchased
order by discount_rate desc
limit 5;

-- Q7 segment customers into new, Returning and loyal based on their total 
-- number of pervious purchase and show the count of each segment

with customer_type as (
select customer_id, previous_purchases,
case
	when previous_purchases = 1 then 'New'
	when previous_purchases between 2 and 10 then 'Returning'
	else 'Loyal'
	end as customer_segment
from customer
)

select customer_segment, count(*) as "Number of Customers"
from customer_type
group by customer_segment

-- Q8 what are the top 3 most purchase products within each category?

with item_count as (
	select category, 
	item_purchased,
	COUNT(customer_id) as total_order,
	ROW_Number() over(partition by category order by count(customer_id)DESC) as item_rank
	from customer
	group by category, item_purchased
)

select item_rank, category, item_purchased, total_order from item_count
where item_rank <= 3;

-- Q9 Are customer who are repeat buyers (more than 5 pervious purchases) also likely to subscribe?

select subscription_status, count(customer_id) as repeat_id
from customer
where previous_purchases > 5
group by subscription_status;

-- Q10 what is the revenu contribution of each age group?

select age_group, SUM(purchase_amount) as total_revenue
from customer
group by age_group
order by total_revenue DESC